"""Argument and configuration handling for the disk-usage viewer."""
import ast
import datetime
import difflib
import json
import os
import re
import sys

from help_text import LONG_HELP, SHORT_HELP

# Short spelling, long spelling, parameter label, repeatable.
SPECS = [
    ('d', 'depth', 'DEPTH', False), ('T', 'threads', 'THREADS', False),
    ('', 'config', 'FILE', False), ('n', 'number-of-lines', 'NUMBER', False),
    ('p', 'full-paths', None, False), ('X', 'ignore-directory', 'PATH', True),
    ('I', 'ignore-all-in-file', 'FILE', False), ('L', 'dereference-links', None, False),
    ('x', 'limit-filesystem', None, False), ('s', 'apparent-size', None, False),
    ('r', 'reverse', None, False), ('c', 'no-colors', None, False),
    ('C', 'force-colors', None, False), ('b', 'no-percent-bars', None, False),
    ('B', 'bars-on-right', None, False), ('z', 'min-size', 'MIN_SIZE', False),
    ('R', 'screen-reader', None, False), ('', 'skip-total', None, False),
    ('f', 'filecount', None, False), ('i', 'ignore-hidden', None, False),
    ('v', 'invert-filter', 'REGEX', True), ('e', 'filter', 'REGEX', True),
    ('t', 'file-types', None, False), ('w', 'terminal-width', 'WIDTH', False),
    ('P', 'no-progress', None, False), ('', 'print-errors', None, False),
    ('D', 'only-dir', None, False), ('F', 'only-file', None, False),
    ('o', 'output-format', 'FORMAT', False), ('S', 'stack-size', 'STACK_SIZE', False),
    ('j', 'output-json', None, False), ('M', 'mtime', 'MTIME', False),
    ('A', 'atime', 'ATIME', False), ('y', 'ctime', 'CTIME', False),
    ('', 'files0-from', 'FILES0_FROM', False), ('', 'files-from', 'FILES_FROM', False),
    ('', 'collapse', 'COLLAPSE', True), ('m', 'filetime', 'FILETIME', False),
    ('h', 'help', None, False), ('V', 'version', None, False),
]
LONG = {v[1]: v for v in SPECS}
SHORT = {v[0]: v for v in SPECS if v[0]}
NUMERIC = {'depth', 'threads', 'number-of-lines', 'terminal-width', 'stack-size'}
FORMAT_VALUES = ['si', 'b', 'k', 'm', 'g', 't', 'kb', 'mb', 'gb', 'tb']
FORMAT_ALIASES = {'kib': 'k', 'mib': 'm', 'gib': 'g', 'tib': 't'}


def program_name():
    return os.path.basename(sys.argv[0]) or 'executable'


def option_label(name):
    spec = LONG[name]
    return '--' + name + ((' <' + spec[2] + '>') if spec[2] else '')


def cli_error(message, usage=None, tip=None):
    text = 'error: ' + message + '\n'
    if tip:
        text += '\n  tip: ' + tip + '\n'
    if usage is not None:
        text += '\nUsage: ' + program_name() + ' ' + usage + '\n'
    text += "\nFor more information, try '--help'.\n"
    sys.stderr.write(text)
    raise SystemExit(2)


def jaro(a, b):
    if a == b:
        return 1.0
    if not a or not b:
        return 0.0
    window = max(len(a), len(b)) // 2 - 1
    window = max(0, window)
    seen_a, seen_b = [False] * len(a), [False] * len(b)
    for i, x in enumerate(a):
        for j in range(max(0, i-window), min(len(b), i+window+1)):
            if not seen_b[j] and x == b[j]:
                seen_a[i] = seen_b[j] = True
                break
    aa = [x for x, hit in zip(a, seen_a) if hit]
    bb = [x for x, hit in zip(b, seen_b) if hit]
    matches = len(aa)
    if not matches:
        return 0.0
    trans = sum(x != y for x, y in zip(aa, bb)) / 2
    base = (matches/len(a) + matches/len(b) + (matches-trans)/matches) / 3
    # The CLI uses a conservative similarity threshold.
    return base


def suggestion(value, choices, cutoff=.8):
    ranked = sorted(((jaro(value, k), i, k) for i, k in enumerate(choices)), reverse=True)
    if ranked and ranked[0][0] > cutoff:
        return ranked[0][2]
    return None


def parse_args(args):
    values, order, paths = {}, [], []

    def usage(extra=None, exclude=(), path_required=None):
        keys = [k for k in order if k not in exclude]
        if extra is not None and extra not in keys:
            keys.append(extra)
        suffix = '<PATH>...' if (paths if path_required is None else path_required) else '[PATH]...'
        return ' '.join([option_label(k) for k in keys] + [suffix])

    def unexpected(token):
        if token.startswith('--'):
            found = suggestion(token[2:].split('=')[0], list(LONG))
            if found:
                cli_error(f"unexpected argument '{token}' found", usage(extra=found),
                          f"a similar argument exists: '--{found}'")
        cli_error(f"unexpected argument '{token}' found", '[OPTIONS] [PATH]...',
                  f"to pass '{token}' as a value, use '-- {token}'")

    def store(spec, value):
        _, key, param, repeat = spec
        if key in values and not repeat:
            cli_error(f"the argument '{option_label(key)}' cannot be used multiple times", '[OPTIONS] [PATH]...')
        if key in NUMERIC:
            if not value:
                why = 'cannot parse integer from empty string'
            elif not re.fullmatch(r'\+?[0-9]+', value):
                why = 'invalid digit found in string'
            elif int(value) > 18446744073709551615:
                why = 'number too large to fit in target type'
            else:
                why = None
            if why:
                cli_error(f"invalid value '{value}' for '{option_label(key)}': {why}")
            value = int(value)
        elif key == 'output-format':
            raw = value
            value = FORMAT_ALIASES.get(value.lower(), value.lower())
            if value not in FORMAT_VALUES:
                hint = suggestion(raw, FORMAT_VALUES)
                msg = f"invalid value '{raw}' for '{option_label(key)}'\n  [possible values: {', '.join(FORMAT_VALUES)}]"
                cli_error(msg, tip=f"a similar value exists: '{hint}'" if hint else None)
        elif key == 'filetime' and value not in ('a', 'c', 'm'):
            cli_error(f"invalid value '{value}' for '{option_label(key)}'\n  [possible values: a, c, m]")
        if repeat:
            values.setdefault(key, []).append(value)
        else:
            values[key] = value
        if key not in order:
            order.append(key)

    index = 0
    while index < len(args):
        token = args[index]
        index += 1
        if token == '--':
            paths.extend(args[index:])
            break
        if token in ('--help', '-h'):
            sys.stdout.write((LONG_HELP if token == '--help' else SHORT_HELP).replace('Usage: executable', 'Usage: ' + program_name()))
            raise SystemExit(0)
        if token in ('--version', '-V'):
            sys.stdout.write('Dust 1.2.3\n')
            raise SystemExit(0)
        if token.startswith('--'):
            key, eq, attached = token[2:].partition('=')
            if key not in LONG:
                unexpected('--' + key)
            spec = LONG[key]
            if spec[2]:
                if eq:
                    val = attached
                elif index == len(args):
                    cli_error(f"a value is required for '{option_label(key)}' but none was supplied")
                else:
                    val = args[index]
                    if val.startswith('-') and val != '-' and key not in ('mtime', 'atime', 'ctime'):
                        if val in ('-h', '--help', '-V', '--version'):
                            return parse_args([val])
                        unexpected(val if val.startswith('--') else val[:2])
                    index += 1
                store(spec, val)
            else:
                if eq:
                    cli_error(f"unexpected value '{attached}' for '--{key}' found; no more were expected", usage(extra=key))
                store(spec, True)
            continue
        if token.startswith('-') and token != '-':
            cluster = token[1:]
            k = 0
            while k < len(cluster):
                char = cluster[k]
                k += 1
                if char == 'h':
                    return parse_args(['-h'])
                if char == 'V':
                    return parse_args(['-V'])
                if char not in SHORT:
                    unexpected('-' + char)
                spec = SHORT[char]
                key = spec[1]
                if spec[2]:
                    if k < len(cluster):
                        val = cluster[k:]
                        if val.startswith('='):
                            val = val[1:]
                        k = len(cluster)
                    elif index == len(args):
                        cli_error(f"a value is required for '{option_label(key)}' but none was supplied")
                    else:
                        val = args[index]
                        if val.startswith('-') and val != '-' and key not in ('mtime', 'atime', 'ctime'):
                            if val in ('-h', '--help', '-V', '--version'):
                                return parse_args([val])
                            unexpected(val if val.startswith('--') else val[:2])
                        index += 1
                    store(spec, val)
                else:
                    store(spec, True)
            continue
        paths.append(token)

    conflicts = [ {'depth', 'file-types'}, {'file-types', 'only-dir'},
                  {'only-dir', 'only-file'}, {'files0-from', 'files-from'} ]
    for key in order:
        for pair in conflicts:
            if key in pair and pair.issubset(values):
                other = next(k for k in pair if k != key)
                cli_error(f"the argument '{option_label(key)}' cannot be used with '{option_label(other)}'",
                          usage(exclude=(other,)))
    return values, paths


CONFIG_KEYS = {
    'reverse': 'reverse', 'display-full-paths': 'full-paths',
    'display-apparent-size': 'apparent-size', 'no-colors': 'no-colors',
    'force-colors': 'force-colors', 'no-bars': 'no-percent-bars',
    'bars-on-right': 'bars-on-right', 'skip-total': 'skip-total',
    'ignore-hidden': 'ignore-hidden', 'output-format': 'output-format',
    'number-of-lines': 'number-of-lines', 'depth': 'depth',
    'only-dir': 'only-dir', 'only-file': 'only-file', 'output-json': 'output-json',
    'screen-reader': 'screen-reader', 'min-size': 'min-size',
    'disable-progress': 'no-progress', 'dereference-links': 'dereference-links',
    'limit-filesystem': 'limit-filesystem',
}


def parse_toml(text):
    """Read scalar/array configuration values, without optional third-party modules."""
    try:
        import tomllib
    except ImportError:
        tomllib = None
    if tomllib:
        return tomllib.loads(text)
    result = {}
    table = ''
    pending = ''
    # Remove comments only outside quoted strings.
    for line in text.splitlines():
        quote, escape, buf = None, False, []
        for c in line:
            if quote is not None:
                buf.append(c)
                if escape:
                    escape = False
                elif c == '\\' and quote == '"':
                    escape = True
                elif c == quote:
                    quote = None
            elif c == '#':
                break
            else:
                buf.append(c)
                if c in "\"'":
                    quote = c
        line = ''.join(buf).strip()
        if not line:
            continue
        line = pending + line
        if line.count('[') > line.count(']') and '=' in line:
            pending = line + ' '
            continue
        pending = ''
        if line.startswith('[') and line.endswith(']'):
            table = line[1:-1].strip()
            continue
        match = re.fullmatch(r'([A-Za-z_0-9-]+|"[^"]+"|\'[^\']+\')\s*=\s*(.+)', line)
        if not match:
            raise ValueError('invalid TOML')
        key, raw = match.groups()
        if key.startswith(('"', "'")):
            key = key[1:-1]
        raw = raw.strip()
        if raw == 'true':
            val = True
        elif raw == 'false':
            val = False
        elif re.fullmatch(r'[+-]?[0-9][0-9_]*', raw):
            val = int(raw.replace('_', ''))
        elif raw.startswith(('"', "'", '[')):
            val = ast.literal_eval(re.sub(r'\btrue\b', 'True', re.sub(r'\bfalse\b', 'False', raw)))
        else:
            try:
                val = float(raw)
            except ValueError:
                # Bare ISO dates are valid TOML values, albeit not used here.
                if re.fullmatch(r'\d{4}-\d{2}-\d{2}.*', raw):
                    val = raw
                else:
                    raise ValueError('invalid TOML')
        if not table:
            if key in result:
                raise ValueError('duplicate key')
            result[key] = val
    if pending:
        raise ValueError('unfinished TOML')
    return result


def load_config(explicit):
    path = explicit
    if path is None:
        home = os.path.expanduser('~')
        options = [os.path.join(home, '.dust.toml'),
                   os.path.join(os.environ.get('XDG_CONFIG_HOME', os.path.join(home, '.config')), 'dust', 'config.toml')]
        path = next((p for p in options if os.path.exists(p)), None)
    if path is None:
        return {}
    if not os.path.exists(path):
        sys.stderr.write('Config file ' + json.dumps(path, ensure_ascii=False) + " doesn't exists\n")
        return {}
    if not path.endswith('.toml'):
        sys.stderr.write(f"Ignoring invalid config file '{path}': don't know how to parse file\n")
        return {}
    try:
        with open(path, encoding='utf-8') as stream:
            raw = parse_toml(stream.read())
        cfg = {}
        for key, dest in CONFIG_KEYS.items():
            if key not in raw:
                continue
            val = raw[key]
            if dest in ('number-of-lines', 'depth'):
                if type(val) is not int or not 0 <= val <= 18446744073709551615:
                    raise ValueError('bad type')
            elif dest in ('output-format', 'min-size'):
                if not isinstance(val, str):
                    raise ValueError('bad type')
            elif type(val) is not bool:
                raise ValueError('bad type')
            cfg[dest] = val
        return cfg
    except (ValueError, OSError, SyntaxError, UnicodeError):
        sys.stderr.write(f"Ignoring invalid config file '{path}': couldn't parse TOML file\n")
        return {}


def panic(message, location, main=True):
    thread = 'main' if main else '<unnamed>'
    sys.stderr.write(f"\nthread '{thread}' ({os.getpid()}) panicked at {location}:\n{message}\n"
                     "note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
    raise SystemExit(101)


def parse_min_size(value):
    if value is None:
        return None
    m = re.match(r'\s*([0-9]+)([^0-9]*)', value)
    if not m:
        return None
    num = int(m[1])
    if num > 18446744073709551615:
        return None
    suffix = m[2].lower()
    if not suffix or suffix[0] in ' .':
        unit = 1
    elif suffix[0] == 'b':
        unit = 1
    elif suffix[0] in 'kmgpt':
        base = 1000 if suffix[1:2] == 'b' else 1024
        unit = base ** ('kmgpt'.index(suffix[0]) + 1)
    else:
        sys.stderr.write(f'Ignoring invalid min-size: {value}\n')
        return None
    return (num * unit) & 18446744073709551615


def compile_pattern(pattern):
    # Handle the commonly used Rust-regex character-class spellings.
    translated = pattern.replace(r'\z', r'\Z')
    translated = translated.replace('[[:digit:]]', '[0-9]').replace('[[:alpha:]]', '[A-Za-z]')
    translated = translated.replace('[[:alnum:]]', '[A-Za-z0-9]').replace('[[:space:]]', r'\s')
    error = None
    pos = 0
    if re.search(r'\(\?[=!]|\(\?<[=!]', pattern):
        error = 'look-around, including look-ahead and look-behind, is not supported'
        pos = pattern.index('(?')
    elif re.search(r'\\[1-9]', pattern):
        error = 'backreferences are not supported'
        pos = re.search(r'\\[1-9]', pattern).start()
    try:
        compiled = re.compile(translated)
    except re.error as e:
        pos = e.pos or 0
        msg = str(e)
        if 'unterminated character set' in msg:
            error = 'unclosed character class'
        elif 'unterminated subpattern' in msg:
            error = 'unclosed group'
        elif 'unbalanced parenthesis' in msg:
            error = 'unopened group'
        elif 'nothing to repeat' in msg:
            error = 'repetition operator missing expression'
        elif 'bad escape' in msg:
            error = 'unrecognized escape sequence'
        else:
            error = msg.split(' at position')[0]
    if error:
