def jaro(a, b):
    if a == b:
        return 1.0
    if not a or not b:
        return 0.0
    window = max(len(a), len(b)) // 2 - 1
    window = max(0, window)
    seen_a, seen_b = [False] * len(a), [False] * len(b)
    for i, x in enumerate(a):
        for j in range(max(0, i-window), min(len(b), i+window+1)):
            if not seen_b[j] and x == b[j]:
                seen_a[i] = seen_b[j] = True
