"""Filesystem measurement and selection of the most significant branches."""
from dataclasses import dataclass, field, replace
import errno
import heapq
import os
import stat
import sys


def path_components(path):
    parts = []
    absolute = path.startswith('/')
    if absolute:
        parts.append('/')
    for part in path.split('/'):
        if not part:
            continue
        if part == '.':
            if not parts and not absolute:
                parts.append('.')
            continue
        parts.append(part)
    return tuple(parts)


def normalize_path(path):
    parts = path_components(path)
    if not parts:
        return ''
    if parts[0] == '/':
        return '/' + '/'.join(parts[1:])
    return '/'.join(parts)


def basename(path):
    if path == '/':
        return '/'
    result = path.rstrip('/').rsplit('/', 1)[-1]
    return result or path


def lossy(text):
    return ''.join('\ufffd' if 0xd800 <= ord(c) <= 0xdfff else c for c in text)


@dataclass(eq=False)
class Node:
    path: str
    size: int
    children: list = field(default_factory=list)
    is_dir: bool = False
    is_file: bool = False
    depth: int = 0
    root: bool = False
    eligible: bool = True
    name: str = None
    artificial: bool = False

    def __post_init__(self):
        if self.name is None:
            self.name = self.path

    def sort_key(self):
        return self.size, path_components(self.name)

    def __lt__(self, other):
        # heapq is a min-heap; rank larger disk consumers before smaller ones.
        return self.sort_key() > other.sort_key()

    def view(self):
        return replace(self, children=[])


class Measurement:
    def __init__(self, options):
        self.opts = options
        self.seen = set()
        self.errors = {}
        self.ignore_paths = set()
        self.root_device = None

