        code = getattr(error, 'errno', errno.ENOENT)
        self.errors.setdefault(code, set()).add(path)

    def regex_match(self, path):
        path = lossy(path)
        include, exclude = self.opts['include_re'], self.opts['exclude_re']
        return (not include or any(r.search(path) for r in include)) and not any(r.search(path) for r in exclude)

