"""Plain-text, colored tree, accessible, and JSON output."""
import json
import math
import os
import stat
import sys
import time
import unicodedata

from cli import FORMAT_ALIASES, panic
from model import basename, lossy


def text_width(text):
    width = 0
    for ch in text:
        if unicodedata.combining(ch) or unicodedata.category(ch) in ('Cc', 'Cf', 'Mn', 'Me'):
            continue
        width += 2 if unicodedata.east_asian_width(ch) in ('W', 'F') else 1
    return width


def human_size(amount, opts):
    if opts.get('filecount'):
        return format(amount, ',d')
    fmt = str(opts.get('output-format', '')).lower()
    fmt = FORMAT_ALIASES.get(fmt, fmt)
    if fmt and fmt != 'si':
        if fmt == 'b':
            return str(amount) + 'B'
        if fmt[0] in 'kmgt':
            exponent = 'kmgt'.index(fmt[0]) + 1
            base = 1000 if len(fmt) > 1 and fmt[1] == 'b' else 1024
            return str(amount // (base ** exponent)) + fmt[0].upper()
    base = 1000 if fmt == 'si' else 1024
    exp = 0
    while exp < 6 and amount >= base ** (exp + 1):
        exp += 1
    if exp == 0:
        return str(amount) + 'B'
    unit = 'BKMGTPE'[exp]
    div = base ** exp
    if amount < 10 * div:
        return format(amount / div, '.1f') + unit
    return str(amount // div) + unit


def date_size(amount):
    try:
        return time.strftime('%Y-%m-%dT%H:%M:%S', time.localtime(amount))
    except (ValueError, OSError, OverflowError):
        return '1970-01-01T00:00:00'


def printable_size(node, opts):
    if opts.get('filecount'):
        return human_size(node.size, opts)
    if opts.get('filetime'):
        return date_size(node.size)
    return human_size(node.size, opts)


