    def __init__(self, opts):
        self.enabled = bool(opts.get('force-colors')) or (sys.stdout.isatty() and not opts.get('no-colors') and 'NO_COLOR' not in os.environ)
        self.styles = {'di': '1;34', 'ex': '1;32', 'pi': '33', 'so': '1;35',
                       'bd': '1;33', 'cd': '1;33', 'ln': '1;36',
                       'su': '37;41', 'sg': '30;43', 'tw': '30;42', 'ow': '34;42', 'st': '37;44'}
