"""Small syntax adapters for Unicode-aware path filters."""
import functools
import re
import unicodedata


class PatternIssue(ValueError):
    def __init__(self, message, offset, length=1):
        super().__init__(message)
        self.message, self.offset, self.length = message, offset, length


CATEGORY_NAMES = {
    'letter': 'L', 'uppercaseletter': 'Lu', 'lowercaseletter': 'Ll',
    'titlecaseletter': 'Lt', 'modifierletter': 'Lm', 'otherletter': 'Lo',
    'mark': 'M', 'nonspacingmark': 'Mn', 'spacingmark': 'Mc', 'enclosingmark': 'Me',
    'number': 'N', 'decimalnumber': 'Nd', 'decimaldigitnumber': 'Nd',
    'letternumber': 'Nl', 'othernumber': 'No', 'punctuation': 'P',
    'connectorpunctuation': 'Pc', 'dashpunctuation': 'Pd',
    'openpunctuation': 'Ps', 'closepunctuation': 'Pe',
    'initialpunctuation': 'Pi', 'finalpunctuation': 'Pf', 'otherpunctuation': 'Po',
    'symbol': 'S', 'mathsymbol': 'Sm', 'currencysymbol': 'Sc',
    'modifiersymbol': 'Sk', 'othersymbol': 'So', 'separator': 'Z',
    'spaceseparator': 'Zs', 'lineseparator': 'Zl', 'paragraphseparator': 'Zp',
    'other': 'C', 'control': 'Cc', 'format': 'Cf', 'privateuse': 'Co',
    'unassigned': 'Cn', 'surrogate': 'Cs',
}
CATEGORIES = {'Lu','Ll','Lt','Lm','Lo','Mn','Mc','Me','Nd','Nl','No','Pc','Pd','Ps','Pe','Pi','Pf','Po','Sm','Sc','Sk','So','Zs','Zl','Zp','Cc','Cf','Cs','Co','Cn'}


def code_escape(number):
    return ('\\u%04x' % number) if number <= 65535 else ('\\U%08x' % number)


@functools.lru_cache(maxsize=32)
def property_ranges(name, complement=False):
    canonical = re.sub(r'[_ -]', '', name).lower()
    if '=' in canonical or ':' in canonical:
        _, canonical = re.split('[=:]', canonical, 1)
    category = CATEGORY_NAMES.get(canonical)
    if category is None:
        category = next((c for c in CATEGORIES | set('LMNPSZC') if c.lower() == canonical), None)
    scripts = {'greek', 'latin', 'cyrillic', 'hebrew', 'arabic', 'hiragana', 'katakana',
               'devanagari', 'bengali', 'thai', 'hangul', 'han', 'armenian', 'georgian'}
    if category:
        predicate = lambda c: unicodedata.category(c).startswith(category)
    elif canonical == 'ascii':
        predicate = lambda c: ord(c) < 128
    elif canonical in ('any', 'assigned'):
        predicate = (lambda c: unicodedata.category(c) not in ('Cn', 'Cs')) if canonical == 'assigned' else (lambda c: True)
    elif canonical in ('alphabetic', 'alpha'):
        predicate = str.isalpha
    elif canonical in ('lowercase', 'lower'):
        predicate = str.islower
    elif canonical in ('uppercase', 'upper'):
        predicate = str.isupper
    elif canonical in ('whitespace', 'space'):
        predicate = lambda c: ord(c) in (9,10,11,12,13,32,133,160,5760,8232,8233,8239,8287,12288) or 8192 <= ord(c) <= 8202
    elif canonical in scripts:
        if canonical == 'han':
            predicate = lambda c: 'CJK' in unicodedata.name(c, '') or unicodedata.name(c, '').startswith('IDEOGRAPHIC')
        else:
            predicate = lambda c: canonical.upper() in unicodedata.name(c, '')
    else:
        raise ValueError('Unicode property not found')
    ranges, start = [], None
    for point in range(0x110000):
        hit = bool(predicate(chr(point))) != complement
        if hit and start is None:
            start = point
        elif not hit and start is not None:
            ranges.append((start, point - 1))
            start = None
    if start is not None:
        ranges.append((start, 0x10ffff))
    return ''.join(code_escape(a) + (('-' + code_escape(b)) if b != a else '') for a, b in ranges)


def translate(pattern):
    """Translate equivalent matching constructs, retaining original error offsets."""
    for match in re.finditer(r'(?<!\\)\{', pattern):
        # Braces in character classes are literal characters.
        left = pattern[:match.start()]
        if left.rfind('[') > left.rfind(']'):
            continue
        offset = match.start()
        rest = pattern[offset+1:]
        if not rest:
            raise PatternIssue('unclosed counted repetition', offset)
        if not rest[0].isdigit():
            raise PatternIssue('repetition quantifier expects a valid decimal', offset+1)
        if '}' not in rest:
            raise PatternIssue('unclosed counted repetition', offset, len(pattern)-offset)
    def property_sub(match):
        letter, braced, single = match.groups()
        prop = braced or single
        before = pattern[:match.start()]
        in_class = before.rfind('[') > before.rfind(']')
        try:
            contents = property_ranges(prop, letter == 'P' and in_class)
        except ValueError as error:
            raise PatternIssue(str(error), match.start(), len(match[0]))
        return contents if in_class else ('[' + ('^' if letter == 'P' else '') + contents + ']')
    result = re.sub(r'\\([pP])(?:\{([^{}]+)\}|([A-Za-z]))', property_sub, pattern)
    result = re.sub(r'\(\?<([A-Za-z_][A-Za-z0-9_]*)>', r'(?P<\1>', result)
    result = re.sub(r'\\[ux]\{([0-9a-fA-F]+)\}', lambda m: code_escape(int(m[1], 16)), result)
    result = result.replace('(?U)', '').replace('(?-U)', '')
    return result
